import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    values = {}
    visiting = set()

    token_re = re.compile(
        r"\s*(?:(\d+)|([A-Z][1-9]\d?)|(<=|>=|<>|[()+\-*/,:=<>]))"
    )

    def tokenize(text):
        tokens = []
        pos = 0
        while pos < len(text):
            match = token_re.match(text, pos)
            if not match:
                raise ValueError("Invalid formula")
            number, cell, symbol = match.groups()
            tokens.append(number if number is not None else
                          cell if cell is not None else symbol)
            pos = match.end()
        return tokens

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in visiting:
            return "#CYCLE!"

        visiting.add(name)
        content = cells[name]
        if content.startswith("="):
            parser = Parser(tokenize(content[1:]))
            value = parser.parse_formula()
        else:
            value = int(content)
        visiting.remove(name)
        values[name] = value
        return value

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def take(self):
            token = self.peek()
            if token is not None:
                self.pos += 1
            return token

        def parse_formula(self):
            return self.parse_add()

        def parse_add(self):
            value = self.parse_mul()
            while self.peek() in ("+", "-"):
                op = self.take()
                if isinstance(value, str):
                    return value
                right = self.parse_mul()
                if isinstance(right, str):
                    return right
                value = value + right if op == "+" else value - right
            return value

        def parse_mul(self):
            value = self.parse_unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                if isinstance(value, str):
                    return value
                right = self.parse_unary()
                if isinstance(right, str):
                    return right
                if op == "*":
                    value *= right
                elif right == 0:
                    value = "#DIV/0!"
                else:
                    quotient = abs(value) // abs(right)
                    value = -quotient if (value < 0) != (right < 0) else quotient
            return value

        def parse_unary(self):
            if self.peek() == "-":
                self.take()
                value = self.parse_unary()
                return value if isinstance(value, str) else -value
            return self.parse_atom()

        def parse_atom(self):
            token = self.take()
            if token is None:
                raise ValueError("Unexpected end of formula")
            if token == "(":
                value = self.parse_formula()
                self.take()
                return value
            if token.isdigit():
                return int(token)
            if token in ("SUM", "MIN", "MAX", "IF"):
                return self.parse_function(token)
            if re.fullmatch(r"[A-Z][1-9]\d?", token):
                return cell_value(token)
            raise ValueError("Invalid atom")

        def parse_function(self, name):
            self.take()  # (
            if name == "IF":
                left = self.parse_formula()
                op = self.take()
                right = self.parse_formula()
                self.take()  # comma
                if isinstance(left, str):
                    self.skip_if_args()
                    return left
                if isinstance(right, str):
                    self.skip_if_args()
                    return right
                condition = {
                    "=": left == right,
                    "<>": left != right,
                    "<": left < right,
                    "<=": left <= right,
                    ">": left > right,
                    ">=": left >= right,
                }[op]
                then_value = self.parse_formula()
                self.take()  # comma
                # Parsing is lazy: skip the unchosen branch's tokens without evaluating it.
                else_start = self.pos
                if condition:
                    return then_value
                self.pos = else_start
                return self.parse_formula()

            aggregate = 0
            seen = False
            while True:
                start = self.pos
                first = self.peek()
                if (first is not None and
                        re.fullmatch(r"[A-Z][1-9]\d?", first) and
                        self.pos + 1 < len(self.tokens) and
                        self.tokens[self.pos + 1] == ":"):
                    first_name = self.take()
                    self.take()
                    second_name = self.take()
                    for name_in_range in self.range_names(first_name, second_name):
                        if name_in_range in cells:
                            item = cell_value(name_in_range)
                            if isinstance(item, str):
                                return item
                            aggregate = self.combine(name, aggregate, item, seen)
                            seen = True
                else:
                    item = self.parse_formula()
                    if isinstance(item, str):
                        return item
                    aggregate = self.combine(name, aggregate, item, seen)
                    seen = True

                if self.peek() == ",":
                    self.take()
                    continue
                self.take()  # )
                return aggregate if seen else 0

        def combine(self, name, aggregate, item, seen):
            if not seen:
                return item
            if name == "SUM":
                return aggregate + item
            if name == "MIN":
                return min(aggregate, item)
            return max(aggregate, item)

        def range_names(self, first, second):
            c1, r1 = ord(first[0]) - 65, int(first[1:])
            c2, r2 = ord(second[0]) - 65, int(second[1:])
            for row in range(min(r1, r2), max(r1, r2) + 1):
                for col in range(min(c1, c2), max(c1, c2) + 1):
                    yield chr(65 + col) + str(row)

        def skip_if_args(self):
            # Consume the remaining IF arguments without evaluating them.
            depth = 0
            while self.pos < len(self.tokens):
                token = self.take()
                if token == "(":
                    depth += 1
                elif token == ")":
                    if depth == 0:
                        return
                    depth -= 1

    for name in cells:
        cell_value(name)
    return {name: values[name] for name in cells}
